          "eyebrow": "How It Works",
          "headline": "From Browse to Keys \u2014 Here's the Play-by-Play",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Step 1 \u2014 Browse",
              "description": "Filter by make, model, year, price, and mileage. Every listing includes photos, specs, and a full history report.",
              "metadata": {
                "step": "1"
              }
            },
            {
              "title": "Step 2 \u2014 Inspect",
              "description": "Read the 120-point inspection report, watch the walkaround video, and ask our team any questions via live chat.",
              "metadata": {
                "step": "2"
