}
.browser-tab {
  background: var(--bevel);
  color: var(--midnight);
  font-family: var(--font-heading);
  font-size: 12px;
  padding: 8px 18px;
  border-top: 2px solid #FFFFFF;
  border-left: 2px solid #FFFFFF;
  border-right: 2px solid var(--chrome);
  border-bottom: 0;
  text-transform: uppercase;
  position: relative;
  top: -2px;
}
.browser-tab.inactive {
  background: var(--chrome);
  color: var(--bevel-darker);
  top: 0;
}

.reserve-grid {
  max-width: var(--content-max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 58fr 38fr;
  gap: 4%;
}
.reserve-form-panel {
  background: var(--bevel);
  border-top: 3px solid #FFFFFF;
  border-left: 3px solid #FFFFFF;
  border-right: 3px solid var(--chrome);
  border-bottom: 3px solid var(--chrome);
  padding: 28px;
  box-shadow: 4px 4px 0 var(--bevel-darker);
}
.reserve-form-panel h2 {
  font-size: 36px;
  color: var(--midnight);
  margin-bottom: 8px;
}
.reserve-form-panel .subhead {
  color: var(--midnight);
  margin-bottom: 20px;
  font-size: 14px;
}
.form-group { margin-bottom: 16px; }
.form-group label {
  display: block;
  font-weight: bold;
  font-size: 13px;
  color: var(--grape);
  margin-bottom: 4px;
}
.form-group .hint {
  font-size: 12px;
  color: #555;
  font-style: italic;
  margin-bottom: 6px;
}
.form-group input,
.form-group select {
  width: 100%;
  padding: 8px;
  background: #FFF;
  border-top: 2px solid var(--bevel-dark);
  border-left: 2px solid var(--bevel-dark);
  border-right: 2px solid #FFFFFF;
  border-bottom: 2px solid #FFFFFF;
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--midnight);
}
.radio-group {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.radio-group label {
  font-weight: normal;
  color: var(--midnight);
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  margin: 0;
}
.form-cta {
  width: 100%;
  margin-top: 12px;
  padding: 16px;
  font-size: 16px;
  display: block;
  text-align: center;
}

.reserve-sidebar {
  background: var(--grape);
  border: 2px solid var(--sky);
  color: var(--bevel);
  padding: 24px;
  display: flex;
  flex-direction: column;
}
.reserve-sidebar h3 {
  font-family: var(--font-accent);
  font-size: 18px;
  color: var(--honk);
  text-transform: uppercase;
  letter-spacing: 0.15em;
  margin-bottom: 16px;
  font-weight: normal;
}
.reserve-sidebar ul {
  list-style: none;
  padding: 0;
  margin: 0 0 24px 0;
}
.reserve-sidebar li {
  font-size: 13px;
  color: var(--bevel);
  padding-left: 24px;
  position: relative;
  margin-bottom: 10px;
  line-height: 1.5;
}
.reserve-sidebar li::before {
  content: '★';
  position: absolute;
  left: 0;
  color: var(--lime);
  font-size: 16px;
}
.reserve-sidebar .hit-counter { margin-top: auto; }

/* guarantee grid */
.guarantee-section {
  background: var(--bevel);
  color: var(--midnight);
  padding: 72px 24px;
  text-align: center;
}
.guarantee-section h2 {
  font-size: 42px;
  color: var(--magenta);
  -webkit-text-stroke: 1.5px var(--midnight);
  margin-bottom: 16px;
}
.guarantee-grid {
  max-width: 880px;
  margin: 32px auto 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.guarantee-card {
  background: var(--bevel);
  border-top: 3px solid #FFFFFF;
  border-left: 3px solid #FFFFFF;
  border-right: 3px solid var(--chrome);
  border-bottom: 3px solid var(--chrome);
  padding: 28px;
  text-align: left;
  box-shadow: 3px 3px 0 var(--bevel-dark);
}
.guarantee-card .gc-icon {
  width: 48px;
  height: 48px;
  border: 2px solid var(--grape);
  padding: 4px;
  margin-bottom: 12px;
  background: #FFF;
}
.guarantee-card h3 {
  font-size: 18px;
  color: var(--grape);
  margin-bottom: 10px;
}
.guarantee-card p {
  font-size: 14px;
  color: var(--midnight);
  margin: 0;
  line-height: 1.65;
}
.guarantee-card .ssl-chip {
  display: inline-block;
  font-family: var(--font-accent);
  font-size: 11px;
  background: var(--midnight);
  color: var(--honk);
  padding: 2px 8px;
  margin-bottom: 8px;
  text-transform: uppercase;
}
.guarantee-section .badge-row {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 32px;
}

/* faq */
.faq-section {
  background: var(--grape);
  padding: 72px 24px 80px;
  position: relative;
  overflow: hidden;
}
.faq-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle, rgba(17,0,34,0.2) 1px, transparent 2px);
  background-size: 24px 24px;
  pointer-events: none;
}
.faq-section .inner {
  position: relative;
  z-index: 2;
  max-width: 800px;
  margin: 0 auto;
}
.faq-section h2 {
  font-size: 32px;
  color: var(--bevel);
  border-left: 3px solid var(--sky);
  padding-left: 16px;
  margin-bottom: 32px;
  max-width: 680px;
  line-height: 1.1;
}
.faq-list {
  list-style: none;
  padding: 0;
  margin: 0 0 32px 0;
}
.faq-item {
  padding: 20px 0;
  border-top: 2px solid;
  border-image: linear-gradient(to right, var(--sky), var(--lime)) 1;
}
.faq-item:nth-child(even) {
  background: rgba(17,0,34,0.08);
  padding: 20px 16px;
}
.faq-item h3 {
  font-size: 18px;
  color: var(--honk);
  margin-bottom: 8px;
}
.faq-item h3::before {
  content: '► ';
  color: var(--lime);
}
.faq-item p {
  color: var(--bevel);
  font-size: 14px;
  margin: 0 0 0 24px;
  line-height: 1.65;
}

.faq-cta-block {
  text-align: center;
  padding-top: 24px;
}
.faq-cta-block .star-line {
  font-size: 13px;
  color: var(--bevel);
  margin: 16px 0;
}
.faq-cta-block .star-line::before, .faq-cta-block .star-line::after {
  content: ' ★ ';
  color: var(--lime);
}
.faq-cta-block .hit-counter { display: inline-flex; }

/* ============== UTILITY ============== */
.row { display: flex; gap: 16px; flex-wrap: wrap; }
.center { text-align: center; }
.spacer-32 { height: 32px; }
.flex-end { display: flex; justify-content: flex-end; }

/* ============== RESPONSIVE ============== */
@media (max-width: 1024px) {
  .hero-home .hero-content { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .stat-block:not(:last-child)::after { display: none; }
  .feature-grid-asym { grid-template-columns: 1fr; }
  .feature-cards { grid-template-columns: 1fr 1fr; }
  .filter-grid { grid-template-columns: 1fr 1fr; }
  .listing-grid { grid-template-columns: 1fr 1fr; }
  .specs-grid { grid-template-columns: 1fr 1fr; }
  .specs-signature .split { grid-template-columns: 1fr; }
  .scorecard-panel { margin-top: 16px; }
  .specs-header .inner { grid-template-columns: 1fr; }
  .specs-card-badge { right: 16px; top: 16px; }
  .gallery-masthead .inner { grid-template-columns: 1fr; }
  .gallery-cards { grid-template-columns: 1fr; }
  .interior-shell { grid-template-columns: 1fr; }
  .mech-grid { grid-template-columns: 1fr; }
  .reserve-grid { grid-template-columns: 1fr; }
  .gallery-cta .inner { grid-template-columns: 1fr; }
  .testimonial-grid { grid-template-columns: 1fr; }
  .testimonial-grid .col-mid { margin-top: 0; }
  .compare-split { grid-template-columns: 1fr; }
  .compare-col.sky-bg { border-left: 0; border-top: 4px solid var(--chrome); }
  .timeline-row { grid-template-columns: 1fr; gap: 12px; text-align: center; }
  .timeline-num { font-size: 64px; }
  .site-footer-inner { grid-template-columns: 1fr 1fr; }
  .reserve-hero-illo { position: relative; top: auto; right: auto; margin: 24px auto 0; width: 100%; max-width: 340px; }
  .guarantee-grid { grid-template-columns: 1fr; }
  .bigcount { font-size: 100px; }
  .specs-signature h2 { font-size: 64px; }
  .reserve-hero h1 { font-size: 56px; }
  .reserve-hero h1 .small { font-size: 32px; }
  .giant-47 { font-size: 120px; }
}

@media (max-width: 640px) {
  .hero-home h1 { font-size: 38px; }
  .hero-marquee-bg .row { font-size: 60px; }
  .stat-value { font-size: 48px; }
  .stats-grid { grid-template-columns: 1fr; }
  .feature-cards { grid-template-columns: 1fr; }
  .filter-grid { grid-template-columns: 1fr; }
  .listing-grid { grid-template-columns: 1fr; }
  .specs-grid { grid-template-columns: 1fr; }
  .bigcount { font-size: 60px; }
  .masthead-product h1 { font-size: 36px; }
  .listings-header h2 { font-size: 32px; }
  .section-magenta h2 { font-size: 36px; }
  .specs-header h1 { font-size: 36px; }
  .specs-signature h2 { font-size: 40px; }
  .gallery-masthead h1 { font-size: 36px; }
  .signature-gallery h2 { font-size: 28px; }
  .interior-section h2 { font-size: 28px; }
  .mech-section h2 { font-size: 28px; }
  .reserve-hero h1 { font-size: 40px; }
  .reserve-hero h1 .small { font-size: 24px; }
  .giant-47 { font-size: 80px; }
  .reserve-card h2 { font-size: 22px; }
  .guarantee-section h2 { font-size: 28px; }
  .faq-section h2 { font-size: 24px; }
  .specs-cta h2 { font-size: 32px; }
  .gallery-cta h2 { font-size: 24px; }
  .site-footer-inner { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; }
}

